/// Server URLs defined in the OpenAPI document.
public enum Servers {
    /// Local development (`npm run dev:api`)
    public enum Server1 {
        /// Local development (`npm run dev:api`)
        public static func url() throws -> Foundation.URL {
            try Foundation.URL(
                validatingOpenAPIServerURL: "http://127.0.0.1:3000",
